6|use Illuminate\Database\Eloquent\Factories\HasFactory;
7|use Illuminate\Database\Eloquent\Model;
8|use Illuminate\Database\Eloquent\Relations\BelongsTo;
9|use Illuminate\Validation\ValidationException;
10|
11|/**
12| * یک نمرهٔ خام.
13| *
14| * «بیست نمرهٔ تکلیف» بیست سطر Grade است، نه یک ستون. نگهداری فقط نمرهٔ
15| * تجمیعی یعنی از دست رفتن ریزنمرات، و کارنامه بدون آن قابل بازسازی نیست.
16| */
17|class Grade extends Model
18|{
19|    use HasFactory;
20|
21|    protected $fillable = [
22|        'student_id',
23|        'course_id',
24|        'user_id',
25|        'type',
26|        'title',
27|        'score',
28|        'max_score',
29|        'graded_at',
30|        'notes',
31|    ];
32|
33|    protected function casts(): array
34|    {
35|        return [
36|            'type' => GradeType::class,
37|            'score' => 'decimal:2',
38|            'max_score' => 'decimal:2',
39|            'graded_at' => 'date',
40|        ];
41|    }
42|
43|    public function student(): BelongsTo
44|    {
45|        return $this->belongsTo(Student::class);
46|    }
47|
48|    public function course(): BelongsTo
49|    {
50|        return $this->belongsTo(Course::class);
51|    }
52|
53|    /** استادی که نمره را ثبت کرده. */
54|    public function user(): BelongsTo
55|    {
56|        return $this->belongsTo(User::class);
57|    }
58|
59|    protected static function booted(): void
60|    {
61|        static::saving(function (self $grade) {
62|            if ((float) $grade->max_score <= 0) {
63|                throw ValidationException::withMessages([
64|                    'max_score' => 'نمرهٔ حداکثر باید بیشتر از صفر باشد.',
65|                ]);
66|            }
67|
68|            // نمرهٔ بیشتر از حداکثر یعنی نمرهٔ غلط ثبت شده؛ سیستم نباید آن را
69|            // بپذیرد و بعد در کارنامه عددی بالاتر از ۲۰ نشان دهد
70|            if ((float) $grade->score > (float) $grade->max_score) {
71|                throw ValidationException::withMessages([
72|                    'score' => 'نمره نمی‌تواند از حداکثر بیشتر باشد.',
73|                ]);
74|            }
75|
76|            if ((float) $grade->score < 0) {
77|                throw ValidationException::withMessages([
78|                    'score' => 'نمره نمی‌تواند منفی باشد.',
79|                ]);
80|            }
81|        });
82|    }
83|
84|    public function typeLabel(): string
85|    {
86|        return $this->type?->label() ?? '—';
87|    }
88|
89|    /** درصد این نمره، مثلاً ۸۵٫۰۰ */
90|    public function percentage(): float
91|    {
92|        return round((float) $this->score / (float) $this->max_score * 100, 2);
93|    }
94|
95|    public function scoreLabel(): string
96|    {
97|        return to_persian_digits(number_format((float) $this->score, 2)).'/'
98|            .to_persian_digits(number_format((float) $this->max_score, 2));
99|    }
100|
101|    public function gradedAtJalali(): ?string
102|    {
103|        return $this->graded_at ? jalali_date($this->graded_at) : null;
104|    }
105|
106|    /**
107|     * ثبت یا اصلاح نمرهٔ یک تکلیف مشخص.
108|     *
109|     * updateOrCreate با کلید ایندکس یکتا هماهنگ است، پس دکمهٔ «ذخیره» دوباره
110|     * زده شود نمره را تکرار نمی‌کند.
111|     */
112|    public static function record(
113|        Student $student,
114|        Course $course,
115|        GradeType $type,
116|        string $title,
117|        float $score,
118|        ?float $maxScore = null,
119|        ?User $by = null,
120|        ?string $gradedAt = null,
121|    ): self {
122|        $maxScore ??= 20.0;
123|
124|        return static::updateOrCreate(
125|            [
126|                'student_id' => $student->id,
127|                'course_id' => $course->id,
128|                'type' => $type->value,
129|                'title' => $title,
130|            ],
131|            [
132|                'score' => $score,
133|                'max_score' => $maxScore,
134|                'user_id' => $by?->id ?? auth()->id(),
135|                'graded_at' => $gradedAt,
136|            ],
137|        );
138|    }
139|
140|    /** نمره‌های یک دانش‌آموز در یک دوره، برای محاسبهٔ میانگین. */
141|    public static function forStudentInCourse(Student $student, Course $course)
142|    {
143|        return static::query()
144|            ->where('student_id', $student->id)
145|            ->where('course_id', $course->id)
146|            ->get();
147|    }
