2|
3|namespace App\Services;
4|
5|use App\Enums\AttendanceStatus;
6|use App\Enums\EnrollmentStatus;
7|use App\Models\Attendance;
8|use App\Models\ClassSession;
9|use App\Models\Grade;
10|use App\Models\Student;
11|use Illuminate\Support\Collection;
12|
13|/**
14| * گزارش‌های آموزشی: حضور در یک بازه، میانگین نمرات، دانش‌آموزان کم‌حضور.
15| *
16| * همهٔ بازه‌ها روی تاریخ جلسه/نمره اعمال می‌شوند، نه روی فاکتور یا ثبت‌نام.
17| * گزارش حضور باید همان جلسات برگزارشده را بشمارد.
18| */
19|class AcademicReport
20|{
21|    public function __construct(
22|        private readonly AttendanceThreshold $threshold = new AttendanceThreshold,
23|        private readonly WeightedAverage $average = new WeightedAverage,
24|    ) {}
25|
26|    /**
27|     * درصد حضور یک دانش‌آموز در یک بازه.
28|     *
29|     * جلسات موجه از مخرج کم می‌شوند: جلسه‌ای که برگزار نشد نباید درصد را
30|     * خراب کند. و اگر هیچ جلسهٔ قابل محاسبه‌ای نبود، null برمی‌گردد نه صفر —
31|     * «۰٪» اتهام است.
32|     *
33|     * @return array{rate: float|null, present: int, absent: int, excused: int, total: int}
34|     */
35|    public function attendanceFor(Student $student, ?string $from = null, ?string $to = null): array
36|    {
37|        $rows = $this->attendanceRows($student, $from, $to);
38|
39|        $counts = [
40|            AttendanceStatus::Present->value => 0,
41|            AttendanceStatus::Absent->value => 0,
42|            AttendanceStatus::Late->value => 0,
43|            AttendanceStatus::Excused->value => 0,
44|        ];
45|
46|        foreach ($rows as $row) {
47|            $counts[$row->status->value] = ($counts[$row->status->value] ?? 0) + 1;
48|        }
49|
50|        // تأخیر یعنی در کلاس بوده، پس در حاضرها می‌شمارد
51|        $present = $counts[AttendanceStatus::Present->value] + $counts[AttendanceStatus::Late->value];
52|        $absent = $counts[AttendanceStatus::Absent->value];
53|        $excused = $counts[AttendanceStatus::Excused->value];
54|        $countable = $present + $absent;
55|
56|        return [
57|            'rate' => $countable === 0 ? null : round($present / $countable * 100, 2),
58|            'present' => $present,
59|            'absent' => $absent,
60|            'excused' => $excused,
61|            'total' => $countable,
62|        ];
63|    }
64|
65|    /** @return Collection<int, Attendance> */
66|    private function attendanceRows(Student $student, ?string $from, ?string $to): Collection
67|    {
68|        return Attendance::query()
69|            ->where('student_id', $student->id)
70|            ->whereHas('classSession', fn ($q) => $q
71|                ->when($from, fn ($s) => $s->whereDate('session_date', '>=', $from))
72|                ->when($to, fn ($s) => $s->whereDate('session_date', '<=', $to)))
73|            ->get();
74|    }
75|
76|    /**
77|     * میانگین نمرهٔ نهایی هر دوره برای یک دانش‌آموز، فقط دوره‌های ثبت‌نام‌شده.
78|     *
79|     * @return Collection<int, array{course: mixed, score: float|null, rank: int|null}>
80|     */
81|    public function gradesFor(Student $student): Collection
82|    {
83|        return $student->enrollments()
84|            ->where('status', EnrollmentStatus::Confirmed->value)
85|            ->with('course.subject')
86|            ->get()
87|            ->map(function ($enrollment) use ($student) {
88|                $ranking = $this->average->rankStudents($enrollment->course);
89|
90|                $row = $ranking->firstWhere('student.id', $student->id);
91|
92|                return [
93|                    'course' => $enrollment->course,
94|                    'score' => $row['score'] ?? $this->average->finalScore($student, $enrollment->course),
95|                    'rank' => $row['rank'] ?? null,
96|                ];
97|            })
98|            ->values();
99|    }
100|
101|    /** میانگین نمره‌های خام یک دانش‌آموز در یک بازه. */
102|    public function rawAverage(Student $student, ?string $from = null, ?string $to = null): ?float
103|    {
104|        $rows = Grade::query()
105|            ->where('student_id', $student->id)
106|            ->when($from, fn ($q) => $q->whereDate('graded_at', '>=', $from))
107|            ->when($to, fn ($q) => $q->whereDate('graded_at', '<=', $to))
108|            ->get();
109|
110|        if ($rows->isEmpty()) {
111|            return null;
112|        }
113|
114|        // میانگین درصدها، نه میانگین نمره‌های خام: یک نمرهٔ ۱۰ از ۱۰ و یک
115|        // نمرهٔ ۲۰ از ۲۰ میانگین ۱۵ می‌دهند و این با میانگین ۱۰ و ۲۰ یکی نیست
116|        return round($rows->sum(fn (Grade $grade) => $grade->percentage()) / $rows->count(), 2);
117|    }
118|
119|    /**
120|     * دانش‌آموزان کم‌حضور، بدترین اول.
121|     *
122|     * دانش‌آموزی که در بازه اصلاً حضور ثبت نشده ندارد در این فهرست نمی‌آید:
123|     * بدون رکورد، نرخی وجود ندارد و «کم‌حضور» دربارهٔ کسی که هنوز سنجیده
124|     * نشده یعنی اتهام بی‌سند.
125|     *
126|     * @param  Collection<int, Student>  $students
127|     * @return Collection<int, array>
128|     */
129|    public function lowAttendance($students, ?string $from = null, ?string $to = null): Collection
130|    {
131|        return $students
132|            ->map(fn (Student $student) => [
133|                'student' => $student,
134|                'attendance' => $this->attendanceFor($student, $from, $to),
135|            ])
136|            ->reject(fn (array $row) => $row['attendance']['rate'] === null)
137|            ->filter(fn (array $row) => $this->threshold->needsAttention($row['attendance']['rate']))
138|            ->sortBy(fn (array $row) => $row['attendance']['rate'])
139|            ->map(function (array $row) {
140|                $row['level'] = $this->threshold->level($row['attendance']['rate']);
141|
142|                return $row;
143|            })
144|            ->values();
145|    }
146|
147|    /**
148|     * جلساتِ برگزارشده در یک بازه — نمایندهٔ مخرجِ گزارش حضور.
149|     *
150|     * «جلسهٔ برگزارشده» یعنی تاریخ مشخص در گذشته؛ جلسهٔ هفتگیِ بدون تاریخ در
151|     * بازه نمی‌افتد چون تاریخی ندارد.
152|     *
153|     * @return Collection<int, ClassSession>
154|     */
155|    public function sessionsIn(?string $from = null, ?string $to = null): Collection
156|    {
157|        return ClassSession::query()
158|            ->whereNotNull('session_date')
159|            ->when($from, fn ($q) => $q->whereDate('session_date', '>=', $from))
160|            ->when($to, fn ($q) => $q->whereDate('session_date', '<=', $to))
161|            ->orderBy('session_date')
162|            ->get();
163|    }
164|
165|    /**
166|     * مقایسهٔ دو بازه برای یک دانش‌آموز: رشد حضور و نمره.
167|     *
168|     * تفاضل، نه درصد تغییر: «رشد ۱۲ واحدی» برای درصد حضور معنی دارد،
169|     * «۲۰٪ رشد» روی ۸۰٪ گمراه‌کننده است.
170|     *
171|     * @return array{attendance_delta: float|null, score_delta: float|null}
172|     */
173|    public function compare(Student $student, array $current, array $previous): array
174|    {
175|        $currentAttendance = $this->attendanceFor($student, $current['from'] ?? null, $current['to'] ?? null);
176|        $previousAttendance = $this->attendanceFor($student, $previous['from'] ?? null, $previous['to'] ?? null);
177|
178|        $currentScore = $this->rawAverage($student, $current['from'] ?? null, $current['to'] ?? null);
179|        $previousScore = $this->rawAverage($student, $previous['from'] ?? null, $previous['to'] ?? null);
180|
181|        return [
182|            'attendance_delta' => $this->delta($currentAttendance['rate'], $previousAttendance['rate']),
183|            'score_delta' => $this->delta($currentScore, $previousScore),
184|        ];
185|    }
186|
187|    /** null اگر یکی از دو نرخ نباشد — نبودن داده، صفر نیست. */
188|    private function delta(?float $current, ?float $previous): ?float
189|    {
190|        if ($current === null || $previous === null) {
191|            return null;
192|        }
193|
194|        return round($current - $previous, 2);
195|    }
196|
197|    /** برچسب رشد/افت برای نمایش. */
198|    public function trendLabel(?float $delta): string
199|    {
200|        if ($delta === null) {
201|            return '—';
202|        }
203|
204|        return match (true) {
205|            $delta > 0 => 'رشد '.to_persian_digits(number_format(abs($delta), 1)),
206|            $delta < 0 => 'افت '.to_persian_digits(number_format(abs($delta), 1)),
207|            default => 'بدون تغییر',
208|        };
209|    }
