32|            // createFromTimestamp, not '@'.$date: the '@' form is parsed as UTC and
33|            // shifts the shamsi day by one depending on the server timezone.
34|            return Jalalian::fromCarbon(Carbon::createFromTimestamp($date, date_default_timezone_get()))->format($format);
35|        }
36|
37|        return Jalalian::fromDateTime($date)->format($format);
38|    }
